402	<body>
403	  <main>
404	    <button type="button" class="circle-container" id="decorative-circle" aria-label="Interactive circle - click to activate, double-click or tap twice to change color" aria-pressed="false" aria-describedby="hint-text">
405	      <svg viewBox="0 0 400 400" aria-hidden="true" role="presentation">
406	        <circle cx="200" cy="200" r="200"/>
407	      </svg>
408	    </button>
409	    <div class="mode-indicator" id="mode-indicator" aria-live="polite" aria-atomic="true"></div>
410	    <div class="hint" id="hint-text" role="status" aria-live="polite" aria-relevant="text">Click or tap to activate</div>
411	    <div class="controls" role="group" aria-label="Circle controls">
412	      <button type="button" class="control-btn" id="cycle-btn" aria-label="Cycle to next color">Cycle Color</button>
413	      <button type="button" class="control-btn" id="reset-btn" aria-label="Reset to default state">Reset</button>
414	    </div>
415	    <div class="keyboard-hint" aria-label="Keyboard shortcuts">Press <kbd>C</kbd> to cycle • <kbd>R</kbd> to reset</div>
416	  </main>
417	
418	  <script defer>
419	    (() => {
420	      const COLORS = [
421	        { class: 'default', name: 'Default White' },
422	        { class: 'color-mode-1', name: 'Pink' },
423	        { class: 'color-mode-2', name: 'Teal' },
424	        { class: 'color-mode-3', name: 'Mint' },
425	        { class: 'color-mode-4', name: 'Purple' },
426	        { class: 'color-mode-5', name: 'Orange' }
427	      ];
428	
429	      const CONFIG = {
430	        storageKey: 'circle-state',
431	        tapDelay: 300,
432	        colorShiftDuration: 500,
433	        saveDebounceDuration: 100,
434	        isTouch: 'ontouchstart' in window || navigator.maxTouchPoints > 0
435	      };
436	
437	      const el = {
438	        circle: document.getElementById('decorative-circle'),
439	        hint: document.getElementById('hint-text'),
440	        modeIndicator: document.getElementById('mode-indicator'),
441	        cycleBtn: document.getElementById('cycle-btn'),
442	        resetBtn: document.getElementById('reset-btn')
443	      };
444	
445	      let state = { active: false, colorMode: 0 };
446	      let tapCount = 0;
447	      let tapTimeout = null;
448	      let animatingColorShift = false;
449	      let saveTimeout = null;
450	
451	      const getColorClass = (mode) => COLORS[mode % COLORS.length].class;
452	      const getColorName = (mode) => COLORS[mode % COLORS.length].name;
453	
454	      const storage = {
455	        save() {
456	          clearTimeout(saveTimeout);
457	          saveTimeout = setTimeout(() => {
458	            try {
459	              localStorage.setItem(CONFIG.storageKey, JSON.stringify(state));
460	            } catch (e) {
461	              if (e.name === 'QuotaExceededError') {
462	                console.warn('Storage quota exceeded');
463	              }
464	            }
465	          }, CONFIG.saveDebounceDuration);
466	        },
467	        load() {
468	          try {
469	            const saved = localStorage.getItem(CONFIG.storageKey);
470	            if (saved) {
471	              const parsed = JSON.parse(saved);
472	              if (parsed?.active !== undefined && parsed?.colorMode !== undefined) {
473	                state = parsed;
474	              }
475	            }
476	          } catch (e) {
477	            // Silent failure - use default state
478	          }
479	        }
480	      };
481	
482	      const updateClasses = () => {
483	        const colorClasses = COLORS.map(m => m.class);
484	        el.circle.classList.remove('active', ...colorClasses);
485	        el.circle.setAttribute('aria-pressed', state.active);
486	        if (state.active) el.circle.classList.add('active');
487	        if (state.colorMode > 0) el.circle.classList.add(getColorClass(state.colorMode));
488	      };
489	
490	      const updateUI = () => {
491	        const hint = CONFIG.isTouch
492	          ? (state.active ? 'Tap twice to cycle • Tap to deactivate' : 'Tap to activate • Tap twice to cycle')
493	          : (state.active ? 'Double-click to cycle • Click to deactivate' : 'Click to activate • Double-click to cycle');
494	        el.hint.textContent = hint;
495	
496	        const showMode = state.active && state.colorMode > 0;
497	        el.modeIndicator.classList.toggle('visible', showMode);
498	        if (showMode) {
499	          el.modeIndicator.textContent = `◆ ${getColorName(state.colorMode).toUpperCase()}`;
500	        }
501	      };
502	
503	      const applyState = () => {
504	        updateClasses();
505	        updateUI();
506	      };
507	
508	      const toggleActive = () => {
509	        state.active = !state.active;
510	        applyState();
511	        storage.save();
512	      };
513	
514	      const cycleColor = () => {
515	        if (animatingColorShift) return;
516	        animatingColorShift = true;
517	        state.colorMode = (state.colorMode + 1) % COLORS.length;
518	        state.active = true;
519	        el.circle.classList.add('color-shifting');
520	        setTimeout(() => {
521	          el.circle.classList.remove('color-shifting');
522	          animatingColorShift = false;
523	        }, CONFIG.colorShiftDuration);
524	        applyState();
525	        storage.save();
526	      };
527	
528	      const resetState = () => {
529	        state = { active: false, colorMode: 0 };
530	        applyState();
531	        storage.save();
532	      };
533	
534	      const handleTouchEnd = () => {
535	        tapCount++;
536	        clearTimeout(tapTimeout);
537	        if (tapCount === 1) {
538	          tapTimeout = setTimeout(() => {
539	            if (tapCount === 1) toggleActive();
540	            tapCount = 0;
541	          }, CONFIG.tapDelay);
542	        } else if (tapCount === 2) {
543	          cycleColor();
544	          tapCount = 0;
545	        }
546	      };
547	
548	      const keyHandlers = {
549	        ' ': toggleActive,
550	        'enter': toggleActive,
551	        'escape': resetState,
552	        'c': cycleColor,
553	        'r': resetState
554	      };
555	
556	      const handleKeyDown = (e) => {
557	        const handler = keyHandlers[e.key.toLowerCase()];
558	        if (handler) {
559	          e.preventDefault();
560	          handler();
561	        }
562	      };
563	
564	      const initListeners = () => {
565	        if (CONFIG.isTouch) {
566	          el.circle.addEventListener('touchend', handleTouchEnd, { passive: true });
567	        } else {
568	          el.circle.addEventListener('click', toggleActive, { passive: true });
569	          el.circle.addEventListener('dblclick', cycleColor, { passive: true });
570	        }
571	        el.circle.addEventListener('blur', () => {
572	          tapCount = 0;
573	          clearTimeout(tapTimeout);
574	        });
575	        document.addEventListener('keydown', handleKeyDown);
576	        el.cycleBtn.addEventListener('click', cycleColor, { passive: true });
577	        el.resetBtn.addEventListener('click', resetState, { passive: true });
578	      };
579	
580	      const initApp = () => {
581	        storage.load();
582	        applyState();
583	        initListeners();
584	        el.circle.focus();
585	      };
586	
587	      const ensureSave = () => {
588	        clearTimeout(saveTimeout);
589	        try {
590	          localStorage.setItem(CONFIG.storageKey, JSON.stringify(state));
591	        } catch (e) {
592	          // Silently fail on storage errors during page hide
593	        }
594	      };
595	
596	      if (document.readyState === 'loading') {
597	        document.addEventListener('DOMContentLoaded', initApp);
